// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use super::compute::compute_grouped_layout;
use super::compute::compute_stacked_layout;
use super::misc::generate_sample_data;
use super::misc::interpolate_layouts;
use super::misc::series_color;
use super::misc::start_animation_loop;
use crate::ShowcaseApp;
use gpui::prelude::*;
use gpui::*;
use gpui_ui_kit::theme::ThemeExt;

/// Layout mode for bar chart
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum BarLayout {
    #[default]
    Stacked,
    Grouped,
}

impl BarLayout {
    pub fn label(&self) -> &'static str {
        match self {
            Self::Stacked => "Stacked",
            Self::Grouped => "Grouped",
        }
    }

    pub fn toggle(&self) -> Self {
        match self {
            Self::Stacked => Self::Grouped,
            Self::Grouped => Self::Stacked,
        }
    }
}

pub fn render(app: &mut ShowcaseApp, cx: &mut Context<ShowcaseApp>) -> Div {
    let entity = cx.entity().clone();
    let theme = cx.theme();

    // Get parameters from app state
    let layout = app.stacked_bars_layout;
    let n_series = app.stacked_bars_n_series;
    let m_samples = app.stacked_bars_m_samples;
    let animation_progress = app.stacked_bars_animation_progress;
    let animating = app.stacked_bars_animating;

    // Generate data
    let data = generate_sample_data(n_series, m_samples);

    // Plot dimensions
    let plot_width = app.content_width as f64;
    let plot_height = (plot_width * 0.5).min(app.content_height as f64 * 0.5);
    let bar_padding = 2.0;

    // Compute both layouts
    let stacked_layout = compute_stacked_layout(&data, plot_width, plot_height, bar_padding);
    let grouped_layout = compute_grouped_layout(&data, plot_width, plot_height, bar_padding);

    // Determine current and target layouts based on animation state
    let current_rects = if animating {
        let (from, to) = match layout {
            BarLayout::Stacked => (&grouped_layout, &stacked_layout),
            BarLayout::Grouped => (&stacked_layout, &grouped_layout),
        };
        interpolate_layouts(from, to, animation_progress)
    } else {
        match layout {
            BarLayout::Stacked => stacked_layout.clone(),
            BarLayout::Grouped => grouped_layout.clone(),
        }
    };

    // Animation loop is now handled by start_animation_loop triggered by actions

    div()
        .flex()
        .flex_col()
        .gap_6()
        // Title
        .child(
            div()
                .flex()
                .flex_col()
                .gap_2()
                .child(
                    div()
                        .text_2xl()
                        .font_weight(FontWeight::BOLD)
                        .child("Stacked to Grouped Bars"),
                )
                .child(
                    div()
                        .text_sm()
                        .child("Ported from Observable: d3/stacked-to-grouped-bars"),
                ),
        )
        // Main content
        .child(
            div()
                .flex()
                .gap_8()
                // Left: Visualization
                .child(
                    div()
                        .flex()
                        .flex_col()
                        .gap_4()
                        .child(
                            div()
                                .flex()
                                .items_center()
                                .gap_3()
                                .child(
                                    div()
                                        .text_lg()
                                        .font_weight(FontWeight::SEMIBOLD)
                                        .child("Animated Bar Chart"),
                                )
                                .child(
                                    div()
                                        .px_2()
                                        .py_1()
                                        .bg(theme.accent)
                                        .rounded_md()
                                        .text_xs()
                                        .child(layout.label()),
                                )
                                .when(animating, |this| {
                                    this.child(
                                        div()
                                            .px_2()
                                            .py_1()
                                            .bg(theme.success)
                                            .rounded_md()
                                            .text_xs()
                                            .child(format!(
                                                "{:.0}%",
                                                animation_progress * 100.0
                                            )),
                                    )
                                }),
                        )
                        .child(
                            div()
                                .w(px(plot_width as f32))
                                .h(px(plot_height as f32))
                                .bg(theme.surface)
                                .border_1()
                                .border_color(theme.border)
                                .rounded_md()
                                .relative()
                                .overflow_hidden()
                                // Render all bars
                                .children(current_rects.iter().enumerate().flat_map(
                                    |(series_idx, series_rects)| {
                                        let color = series_color(series_idx, n_series);
                                        series_rects.iter().map(move |&(x, y, w, h)| {
                                            div()
                                                .absolute()
                                                .left(px(x as f32))
                                                .top(px(y as f32))
                                                .w(px(w as f32))
                                                .h(px(h.max(0.0) as f32))
                                                .bg(color.to_rgba())
                                        })
                                    },
                                )),
                        )
                        // X-axis labels (simplified)
                        .child(
                            div()
                                .flex()
                                .justify_between()
                                .w(px(plot_width as f32))
                                .mt_1()
                                .text_xs()
                                .child("0")
                                .child(format!("{}", m_samples / 2))
                                .child(format!("{}", m_samples)),
                        ),
                )
                // Right: Controls
                .child(
                    div()
                        .w(px(280.0))
                        .flex()
                        .flex_col()
                        .gap_4()
                        // Toggle button
                        .child(
                            div()
                                .flex()
                                .flex_col()
                                .gap_3()
                                .p_4()
                                .bg(theme.surface)
                                .border_1()
                                .border_color(theme.border)
                                .rounded_lg()
                                .child(
                                    div()
                                        .text_lg()
                                        .font_weight(FontWeight::SEMIBOLD)
                                        .child("Layout"),
                                )
                                .child({
                                    let entity = entity.clone();
                                    let disabled = animating;
                                    div()
                                        .id("toggle-layout")
                                        .px_4()
                                        .py_2()
                                        .bg(if disabled {
                                            rgb(0xcccccc)
                                        } else {
                                            rgb(0x007acc)
                                        })
                                        .when(!disabled, |this| {
                                            this.hover(|s| s.bg(theme.accent_hover))
                                        })
                                        .rounded_md()
                                        .cursor(if disabled {
                                            CursorStyle::default()
                                        } else {
                                            CursorStyle::PointingHand
                                        })
                                        .text_sm()
                                        .text_center()
                                        .child(format!(
                                            "Switch to {}",
                                            layout.toggle().label()
                                        ))
                                        .when(!disabled, |this| {
                                            this.on_click(move |_, _window, cx| {
                                                let entity_clone = entity.clone();
                                                entity.update(cx, |this, cx| {
                                                    if !this.stacked_bars_animating {
                                                        this.stacked_bars_layout =
                                                            this.stacked_bars_layout.toggle();
                                                        this.stacked_bars_animating = true;
                                                        this.stacked_bars_animation_progress = 0.0;
                                                        cx.notify();
                                                        start_animation_loop(entity_clone, cx);
                                                    }
                                                });
                                            })
                                        })
                                })
                                // Layout buttons
                                .child(
                                    div()
                                        .flex()
                                        .gap_2()
                                        .children(
                                            [BarLayout::Stacked, BarLayout::Grouped]
                                                .iter()
                                                .map(|&l| {
                                                    let entity = entity.clone();
                                                    let is_selected = l == layout && !animating;
                                                    let bg = if is_selected {
                                                        theme.accent
                                                    } else {
                                                        theme.surface_hover
                                                    };
                                                    let text_color = if is_selected {
                                                        theme.text_on_accent
                                                    } else {
                                                        theme.text_primary
                                                    };

                                                    div()
                                                        .id(ElementId::Name(
                                                            format!("layout-{}", l.label()).into(),
                                                        ))
                                                        .flex_1()
                                                        .px_3()
                                                        .py_2()
                                                        .bg(bg)
                                                        .hover(|s| s.opacity(0.8))
                                                        .rounded_md()
                                                        .cursor_pointer()
                                                        .text_xs()
                                                        .text_color(text_color)
                                                        .text_center()
                                                        .child(l.label())
                                                        .on_click(move |_, _window, cx| {
                                                            let entity_clone = entity.clone();
                                                            entity.update(cx, |this, cx| {
                                                                if !this.stacked_bars_animating
                                                                    && this.stacked_bars_layout != l
                                                                {
                                                                    this.stacked_bars_layout = l;
                                                                    this.stacked_bars_animating =
                                                                        true;
                                                                    this
                                                                        .stacked_bars_animation_progress = 0.0;
                                                                    cx.notify();
                                                                    start_animation_loop(entity_clone, cx);
                                                                }
                                                            });
                                                        })
                                                }),
                                        ),
                                ),
                        )
                        // Data parameters
                        .child(
                            div()
                                .flex()
                                .flex_col()
                                .gap_2()
                                .p_4()
                                .bg(theme.surface)
                                .border_1()
                                .border_color(theme.border)
                                .rounded_lg()
                                .child(
                                    div()
                                        .text_xs()
                                        .font_weight(FontWeight::MEDIUM)
                                        .child("DATA PARAMETERS"),
                                )
                                .child(
                                    div()
                                        .flex()
                                        .items_center()
                                        .justify_between()
                                        .child(
                                            div()
                                                .text_sm()
                                                .child("Series"),
                                        )
                                        .child({
                                            let entity = entity.clone();
                                            div()
                                                .flex()
                                                .gap_1()
                                                .children([3_usize, 4, 5, 6].iter().map(|&n| {
                                                    let entity = entity.clone();
                                                    let is_selected = n == n_series;
                                                    let bg = if is_selected {
                                                        theme.accent
                                                    } else {
                                                        theme.surface_hover
                                                    };
                                                    let text_color = if is_selected {
                                                        theme.text_on_accent
                                                    } else {
                                                        theme.text_primary
                                                    };

                                                    div()
                                                        .id(ElementId::Name(
                                                            format!("series-{}", n).into(),
                                                        ))
                                                        .px_2()
                                                        .py_1()
                                                        .bg(bg)
                                                        .hover(|s| s.opacity(0.8))
                                                        .rounded_sm()
                                                        .cursor_pointer()
                                                        .text_xs()
                                                        .text_color(text_color)
                                                        .child(format!("{}", n))
                                                        .on_click(move |_, _window, cx| {
                                                            entity.update(cx, |this, _| {
                                                                this.stacked_bars_n_series = n;
                                                            });
                                                        })
                                                }))
                                        }),
                                )
                                .child(
                                    div()
                                        .flex()
                                        .items_center()
                                        .justify_between()
                                        .child(
                                            div()
                                                .text_sm()
                                                .child("Samples"),
                                        )
                                        .child({
                                            let entity = entity.clone();
                                            div()
                                                .flex()
                                                .gap_1()
                                                .children(
                                                    [20_usize, 30, 40, 50].iter().map(|&m| {
                                                        let entity = entity.clone();
                                                        let is_selected = m == m_samples;
                                                        let bg = if is_selected {
                                                            theme.accent
                                                        } else {
                                                            theme.surface_hover
                                                        };
                                                        let text_color = if is_selected {
                                                            theme.text_on_accent
                                                        } else {
                                                            theme.text_primary
                                                        };

                                                        div()
                                                            .id(ElementId::Name(
                                                                format!("samples-{}", m).into(),
                                                            ))
                                                            .px_2()
                                                            .py_1()
                                                            .bg(bg)
                                                            .hover(|s| s.opacity(0.8))
                                                            .rounded_sm()
                                                            .cursor_pointer()
                                                            .text_xs()
                                                            .text_color(text_color)
                                                            .child(format!("{}", m))
                                                            .on_click(move |_, _window, cx| {
                                                                entity.update(cx, |this, _| {
                                                                    this.stacked_bars_m_samples = m;
                                                                });
                                                            })
                                                    }),
                                                )
                                        }),
                                ),
                        )
                        // Legend
                        .child(
                            div()
                                .flex()
                                .flex_col()
                                .gap_2()
                                .p_4()
                                .bg(theme.surface)
                                .border_1()
                                .border_color(theme.border)
                                .rounded_lg()
                                .child(
                                    div()
                                        .text_xs()
                                        .font_weight(FontWeight::MEDIUM)
                                        .child("SERIES"),
                                )
                                .child(
                                    div()
                                        .flex()
                                        .flex_wrap()
                                        .gap_2()
                                        .children((0..n_series).map(|i| {
                                            let color = series_color(i, n_series);
                                            div()
                                                .flex()
                                                .items_center()
                                                .gap_1()
                                                .child(
                                                    div()
                                                        .w(px(12.0))
                                                        .h(px(12.0))
                                                        .rounded_sm()
                                                        .bg(color.to_rgba()),
                                                )
                                                .child(
                                                    div()
                                                        .text_xs()
                                                        .child(format!("S{}", i + 1)),
                                                )
                                        })),
                                ),
                        )
                        // Animation info
                        .child(
                            div()
                                .flex()
                                .flex_col()
                                .gap_2()
                                .p_4()
                                .bg(rgb(0x1e1e1e))
                                .border_1()
                                .border_color(rgb(0x333333))
                                .rounded_lg()
                                .child(
                                    div()
                                        .text_xs()
                                        .font_weight(FontWeight::MEDIUM)
                                        .child("ANIMATION"),
                                )
                                .child(
                                    div().text_xs().child(
                                        "Click 'Switch' or the layout buttons to animate between stacked and grouped views. The transition uses cubic ease-in-out for smooth motion.",
                                    ),
                                ),
                        ),
                ),
        )
}
